INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Technik zur Ist-Aufnahme immer Softwaretools benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Methoden möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft dir, den aktuellen Zustand eines Netzwerks zu erfassen?', 3, '[{"text": "Nmap", "correct": true, "because": "Scant Netzwerke"}, {"text": "Notepad", "correct": false, "because": "Nur Text"}, {"text": "Browser", "correct": false, "because": "Kein Analysetool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutzt du, um den Ist-Zustand eines Systems zu dokumentieren?', 5, '[{"text": "Interviews", "correct": true, "because": "Nutzerwissen sammeln"}, {"text": "Netzwerkscans", "correct": true, "because": "Geräte erfassen"}, {"text": "Protokollanalyse", "correct": true, "because": "Datenverkehr prüfen"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerkscans zeigen aktive Geräte. b) Interviews sind immer automatisiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Interviews manuell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was übersehst du, wenn du den Ist-Zustand eines Systems erfasst?', 4, '[{"text": "Netzwerkgeräte", "correct": false, "because": "Müssen erfasst werden"}, {"text": "Softwareversionen", "correct": false, "because": "Wichtig für Analyse"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Ist-Aufnahme nur mit Tools möglich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch manuell machbar"}, {"text": "Ja", "correct": false, "because": "Flexibel umsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik hilft dir, die installierte Software auf einem System zu erfassen?', 3, '[{"text": "Inventarisierungstools", "correct": true, "because": "Listen Software auf"}, {"text": "Ping", "correct": false, "because": "Nur Erreichbarkeit"}, {"text": "Traceroute", "correct": false, "because": "Netzwerkpfade"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine systematische Ist-Aufnahme?', 5, '[{"text": "Vollständigkeit", "correct": true, "because": "Alle Komponenten erfasst"}, {"text": "Planungsgrundlage", "correct": true, "because": "Basis für Änderungen"}, {"text": "Fehlererkennung", "correct": true, "because": "Probleme sichtbar"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Nmap Netzwerke scannt und b) Excel allein ausreicht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Excel nur Dokumentation"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauchst du nicht, um den Ist-Zustand eines Netzwerks zu erfassen?', 4, '[{"text": "Netzwerkscanner", "correct": false, "because": "Erfasst Geräte"}, {"text": "Dokumentation", "correct": false, "because": "Festhaltung nötig"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Ist-Aufnahme immer automatisiert?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Methoden möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken helfen, den Ist-Zustand eines Systems zu analysieren?', 4, '[{"text": "Portscans", "correct": true, "because": "Offene Dienste finden"}, {"text": "Fragebögen", "correct": true, "because": "Nutzerinformationen"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Ist-Aufnahme nur Hardware betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software erfasst"}, {"text": "Ja", "correct": false, "because": "Umfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgst du mit einer Ist-Aufnahme?', 3, '[{"text": "Systemübersicht", "correct": true, "because": "Dokumentiert Zustand"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wireshark analysiert Datenverkehr. b) Manuelle Erfassung ist veraltet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Manuell noch relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt eine Bestandsaufnahme?', 4, '[{"text": "Grundlage schaffen", "correct": true, "because": "Für Planung nötig"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Anderer Zweck"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Ist-Aufnahme immer Netzwerke betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Systeme allein"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
